1	// "Delete the folder and it's gone" as a check: the app keeps everything it
2	// persists under `~/Library/Application Support/LaughCounter/`, so the only
3	// system directory its sources may ask macOS for is the Application Support
4	// one. Scans `mac/Sources/` for the APIs that *select* a search-path directory
5	// and requires the literal `.applicationSupportDirectory`.
6	//
7	// A whitelist, not a blacklist. Earlier sweeps left this rule as prose because
8	// proving "nothing lands outside the directory" looked like it needed data-flow
9	// tracking of every write target back to its declaration. It doesn't: every
10	// persistent path in the app is rooted at a `FileManager` search-path lookup,
11	// and there are exactly two of them (`AppLog.swift`, `Store.swift`), both
12	// `.applicationSupportDirectory`. Constraining the *root* constrains every path
13	// derived from it, and matching the allowed constant positively means a
14	// `SearchPathDirectory` case that doesn't exist yet is caught the day it lands —
15	// which an enumerate-the-bad-ones list would miss.
16	//
17	// Two deliberate consequences, both wanted:
18	//   - A non-literal argument (`urls(for: dir, in:)`) is a finding. Indirection
19	//     is exactly what would defeat the check, and no caller needs it here.
20	//   - The Login Item registration RULES.md carves out doesn't go through these
21	//     APIs at all (`SMAppService` names no directory), so it needs no exemption.
22	//
23	// Dependency-free by design (a local pack must load without the canon mount),
24	// so the finding object is built by hand rather than via the engine helper.
25	
26	const ALLOWED = 'applicationSupportDirectory';
27	
28	// The APIs that pick a system directory. `\s*` spans newlines, so a call split
29	// across lines (`urls(\n    for: .cachesDirectory,`) is matched too.
30	const SELECTORS = [
31	  // FileManager.default.urls(for:in:) and .url(for:in:appropriateFor:create:)
32	  [/\burls?\s*\(\s*for\s*:\s*([^,\s)]+)/g, 'FileManager.urls(for:)'],
33	  [/\bNSSearchPathForDirectoriesInDomains\s*\(\s*([^,\s)]+)/g, 'NSSearchPathForDirectoriesInDomains'],
34	];
35	
36	const inScope = (f) => f.startsWith('mac/Sources/') && f.endsWith('.swift');
37	
38	// `.applicationSupportDirectory`, `FileManager.SearchPathDirectory.applicationSupportDirectory`
39	// and a bare `applicationSupportDirectory` all name the same case.
40	const caseName = (token) => token.replace(/^.*\./, '');
41	
42	const rule = {
43	  id: 'on-device-privacy/single-storage-directory',
44	  severity: 'blocking',
45	  description: 'The app asks macOS for only one directory: .applicationSupportDirectory (mac/Sources/)',
46	  doc: '.claudinite/local/packs/on-device-privacy/RULES.md',
47	  why: '"delete the folder and it\'s gone" is a promise a user acts on — a second storage root means the mic\'s memory of them outlives the directory they deleted',
48	
49	  run(ctx) {
50	    const out = [];
51	    for (const file of ctx.files.filter(inScope)) {
52	      const text = ctx.read(file);
53	      if (text === null) continue;
54	      for (const [pattern, what] of SELECTORS) {
55	        pattern.lastIndex = 0;
56	        let m = pattern.exec(text);
57	        while (m !== null) {
58	          const token = m[1];
59	          if (caseName(token) !== ALLOWED) {
60	            out.push({
61	              rule: rule.id,
62	              severity: rule.severity,
63	              file,
64	              line: text.slice(0, m.index).split('\n').length,
65	              what: `${what} asks for \`${token}\`, not \`.${ALLOWED}\` (${file})`,
66	              why: rule.why,
67	              fix: `root the path at \`FileManager.default.urls(for: .${ALLOWED}, in: .userDomainMask)[0]\` and hang it off the app's existing \`LaughCounter\` directory; a second storage root is a product decision that belongs in RULES.md first`,
68	              doc: rule.doc,
69	            });
70	          }
71	          m = pattern.exec(text);
72	        }
73	      }
74	    }
75	    return out;
76	  },
77	};
78	
79	export default rule;
